// humanRelative renders a signed duration as a human string. Positive d
// (time.Since-style — the moment is in the past) reads as elapsed:
// "5m ago". Negative d (the moment is still ahead) reads as remaining:
// "in 5m". Within a minute of now in either direction reads "just now".
// Shared by TimeAgo and TimeUntil.
func humanRelative(d Duration) string {
	secs := int64(d.Seconds())
	if secs < 60 && secs > -60 {
		return "just now"
	}
	prefix := ""
	suffix := " ago"
	if secs < 0 {
		prefix = "in "
		suffix = ""
		secs = -secs
	}
	mins := secs / 60
	if mins < 60 {
		return fmt.Sprintf("%v%vm%v", prefix, mins, suffix)
	}
	hours := mins / 60
	if hours < 24 {
		return fmt.Sprintf("%v%vh%v", prefix, hours, suffix)
	}
	days := hours / 24
	if days < 30 {
		return fmt.Sprintf("%v%vd%v", prefix, days, suffix)
	}
	months := days / 30
	if months < 12 {
		return fmt.Sprintf("%v%vmo%v", prefix, months, suffix)
	}
	years := days / 365
	return fmt.Sprintf("%v%vy%v", prefix, years, suffix)
}

